inline_styles:
:root {
    --bg: #0a0e17;
    --panel: #131722;
    --panel-2: #1e222d;
    --border: #2a2e39;
    --hover: #2a2e39;
    --text: #d1d4dc;
    --text-dim: #787b86;
    --accent: #2962ff;
    --accent-hover: #1e53e5;
    --green: #26a69a;
    --red: #ef5350;
    --radius: 6px;
    --toolbar-h: 48px;
}

[data-theme="light"] {
    --bg: #ffffff;
    --panel: #f7f8fa;
    --panel-2: #eef1f5;
    --border: #e0e3eb;
    --hover: #e4e8ee;
    --text: #131722;
    --text-dim: #606060;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: 'Segoe UI', Tahoma, system-ui, -apple-system, sans-serif;
}

html, body {
    height: 100%;
    overflow: hidden;
    background: var(--bg);
    color: var(--text);
    font-size: 13px;
    -webkit-font-smoothing: antialiased;
}

/* ========== Layout ========== */
.app {
    display: grid;
    grid-template-rows: var(--toolbar-h) 1fr;
    height: 100vh;
    width: 100vw;
}

/* ========== Toolbar ========== */
.toolbar {
    display: flex;
    align-items: center;
    background: var(--panel);
    border-bottom: 1px solid var(--border);
    padding: 0 12px;
    gap: 12px;
    z-index: 100;
}

.brand {
    display: flex;
    align-items: center;
    gap: 8px;
    padding-left: 12px;
    border-left: 1px solid var(--border);
    height: 100%;
}

.brand-icon {
    width: 28px;
    height: 28px;
    border-radius: var(--radius);
    background: linear-gradient(135deg, var(--accent), #7e57c2);
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-size: 13px;
    box-shadow: 0 3px 10px rgba(41, 98, 255, 0.35);
}

.brand-name {
    font-size: 14px;
    font-weight: 700;
    letter-spacing: -0.2px;
}

.brand-name span {
    color: var(--accent);
}

/* ========== Layout Switcher ========== */
.layout-switcher {
    display: flex;
    gap: 2px;
    background: var(--panel-2);
    padding: 3px;
    border-radius: var(--radius);
    height: 34px;
    align-items: center;
}

.layout-btn {
    width: 32px;
    height: 28px;
    background: transparent;
    border: none;
    border-radius: 4px;
    color: var(--text-dim);
    cursor: pointer;
    display: flex;
